CREATE TABLE `SavedSecretResource` (`id` VARCHAR(191) NOT NULL, `ownerAccountId` VARCHAR(191) NOT NULL, `displayName` VARCHAR(191) NOT NULL, `kind` VARCHAR(191) NOT NULL, `encryptionMode` VARCHAR(191) NOT NULL, `revision` INTEGER NOT NULL DEFAULT 1, `storedContent` LONGTEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SavedSecretAccountGrant` (`resourceId` VARCHAR(191) NOT NULL, `accountId` VARCHAR(191) NOT NULL, `createdByAccountId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`resourceId`,`accountId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SavedSecretTeamGrant` (`resourceId` VARCHAR(191) NOT NULL, `teamId` VARCHAR(191) NOT NULL, `createdByAccountId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`resourceId`,`teamId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SavedSecretGroupGrant` (`resourceId` VARCHAR(191) NOT NULL, `teamGroupId` VARCHAR(191) NOT NULL, `createdByAccountId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`resourceId`,`teamGroupId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SavedSecretResourceKeyEnvelope` (`resourceId` VARCHAR(191) NOT NULL, `recipientAccountId` VARCHAR(191) NOT NULL, `encryptedDataKey` LONGBLOB NOT NULL, `recipientContentPublicKeyFingerprint` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`resourceId`,`recipientAccountId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE INDEX `SavedSecretResource_owner_updated_idx` ON `SavedSecretResource`(`ownerAccountId`,`updatedAt`);
CREATE INDEX `SavedSecretAccountGrant_accountId_resourceId_idx` ON `SavedSecretAccountGrant`(`accountId`,`resourceId`);
CREATE INDEX `SavedSecretTeamGrant_teamId_resourceId_idx` ON `SavedSecretTeamGrant`(`teamId`,`resourceId`);
